  return (ctx.query('orders.orders', { where: { orderId }, limit: 1 }) ?? []).length > 0;
}

function orderOfFulfilment(fid, ctx) {
  if (!fid) return null;
  const row = (ctx.query('orders.fulfilments', { where: { fulfilmentId: fid }, limit: 1 }) ?? [])[0];
  return row ? row.orderId : null;
}

