test('a stop with a charge in flight: nothing new; the charge is refunded, then the items released, when it commits (R5.1, R6.2)', () => {
  let s = fx.step(start, opts(null)).state;
  s = fx.onEvent(reserveOk, opts(fx.step({ op: 'advance' }, opts(s)).state)).state;     // charge now in flight
  const stopped = fx.step({ op: 'stop', at: T2 }, opts(s));
  // the reserved items are held until the charge settles (reverse order); nothing new is charged or booked
  assert.deepEqual(stopped.effects.map(e => e.op), []);
  assert.equal(stopped.output.state, 'stopped');
  const late = fx.onEvent(result('charge', 'billing', 'charge', 'ok'), opts(stopped.state));
  assert.deepEqual(late.effects.map(e => e.op), ['refund', 'release', 'release']);
  assert.equal(late.effects.some(e => e.op === 'create'), false);
});

test('a stop with a shipment in flight: the shipment is cancelled, then the charge refunded, when it commits (R5.1, S14)', () => {
  let s = fx.step(start, opts(null)).state;
  s = fx.onEvent(reserveOk, opts(fx.step({ op: 'advance' }, opts(s)).state)).state;
  s = fx.onEvent(result('charge', 'billing', 'charge', 'ok'), opts(s)).state;          // shipment now in flight
  const stopped = fx.step({ op: 'stop', at: T2 }, opts(s));
  assert.deepEqual(stopped.effects.map(e => e.op), []);                                 // no refund before the shipment settles
  const late = fx.onEvent(result('ship', 'carrier', 'create', 'ok'), opts(stopped.state));
  assert.deepEqual(late.effects.map(e => e.op), ['cancel', 'refund', 'release', 'release']);
});

